public static class ParkingContentExport {
 public static void Run(){
  PlayerSettings.SetUseDefaultGraphicsAPIs(BuildTarget.StandaloneWindows64,false);PlayerSettings.SetGraphicsAPIs(BuildTarget.StandaloneWindows64,new[]{GraphicsDeviceType.Direct3D11});GraphicsSettings.renderPipelineAsset=AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Parking/Settings/ParkingURP.asset");QualitySettings.renderPipeline=GraphicsSettings.renderPipelineAsset;
  EditorSceneManager.OpenScene("Assets/Parking/Scenes/Parking.unity");var source=UnityEngine.Object.FindObjectOfType<ParkingAtmosphere>();if(!source)throw new InvalidOperationException("parking-source-missing");
  CheckHdrEncoding();
  CheckTexturePixels();
  var root=source.transform;
  // Consume the installed author's Bakery registration once, then retain its
  // actual maps and per-renderer bindings as SDK data. No Bakery code is packed.
  ftLightmaps.RefreshFull();var maps=LightmapSettings.lightmaps;var mode=LightmapSettings.lightmapsMode;var renderers=root.GetComponentsInChildren<MeshRenderer>(true);var indices=renderers.Select(r=>r.lightmapIndex).ToArray();var offsets=renderers.Select(r=>r.lightmapScaleOffset).ToArray();
  var lightStates=root.GetComponentsInChildren<Light>(true).ToDictionary(l=>l,l=>l.bakingOutput);
  var removed=new List<string>();foreach(var component in root.GetComponentsInChildren<MonoBehaviour>(true))if(component is BakeryLightmappedPrefab||component is ftLightmapsStorage||component is BakeryPointLight||component is BakeryDirectLight||component is BakerySkyLight||component is BakeryLightmapGroupSelector){removed.Add(component.GetType().Name);UnityEngine.Object.DestroyImmediate(component);}
  LightmapSettings.lightmaps=maps;LightmapSettings.lightmapsMode=mode;for(int i=0;i<renderers.Length;i++){renderers[i].lightmapIndex=indices[i];renderers[i].lightmapScaleOffset=offsets[i];}
  foreach(var state in lightStates)state.Key.bakingOutput=state.Value;
  var definition=new GameObject("SDK Author").AddComponent<SceneDefinition>();definition.contentRoot=root;definition.templateId="6371400c-69c2-4ca6-91cf-91958f54dff2";definition.displayName="Parking";definition.authorFrame=new Vector3(.53f,.298125f,360*.53f/12);definition.licenseSource="Local user asset restoration; see project dependency records";
  var presentation=root.gameObject.AddComponent<ScenePresentationSettings>();var environment=root.GetComponent<ParkingEnvironmentBinding>();if(environment){presentation.customAmbient=true;presentation.ambientIrradiance=environment.irradiance;UnityEngine.Object.DestroyImmediate(environment);}
  presentation.customBackground=true;presentation.backgroundColor=UnityEngine.Object.FindObjectsOfType<Camera>().Single(c=>c.name=="DisplayCamera").backgroundColor;
  presentation.customClipDepth=true;presentation.clipDepth=UnityEngine.Object.FindObjectsOfType<WindowProjection>().Single().contentDepth;
  var volume=root.GetComponentInChildren<Volume>();if(volume){var profile=volume.sharedProfile;presentation.postProcessing=true;if(profile.TryGet<Bloom>(out var bloom))presentation.bloom=new Vector3(bloom.threshold.value,bloom.intensity.value,bloom.scatter.value);if(profile.TryGet<Tonemapping>(out var tone))presentation.aces=tone.mode.value==TonemappingMode.ACES;if(profile.TryGet<ColorAdjustments>(out var color)){presentation.exposure=color.postExposure.value;presentation.saturation=color.saturation.value;}if(profile.TryGet<Vignette>(out var vignette))presentation.vignette=new Vector2(vignette.intensity.value,vignette.smoothness.value);foreach(var component in profile.components)if(!(component is Bloom||component is Tonemapping||component is ColorAdjustments||component is Vignette))throw new InvalidOperationException("unsupported-parking-grade");UnityEngine.Object.DestroyImmediate(volume);}
  var oldField=root.GetComponent<ParkingLampField>();if(oldField){var field=root.gameObject.AddComponent<InstanceField>();field.mesh=oldField.mesh;field.materials=oldField.materials;field.positions=oldField.positions;field.instanceScale=oldField.instanceScale;UnityEngine.Object.DestroyImmediate(oldField);}
