  var lamp=root.gameObject.AddComponent<SignalBindings>();lamp.kind=SignalKind.Intermittent;var lampMaterials=new List<MaterialSignalBinding>{new MaterialSignalBinding{material=source.ground.sharedMaterial,property="_Lamp"}};foreach(var m in fixture)if(m.HasProperty("_LampEmission"))lampMaterials.Add(new MaterialSignalBinding{material=m,property="_LampEmission",kind=MaterialSignalKind.Color,basis=new Vector4(.65f,.8f,1,1),gain=3});lamp.materials=lampMaterials.ToArray();lamp.lights=source.streetLight?new[]{new LightSignalBinding{light=source.streetLight,intensity=.12f*ratio*ratio}}:Array.Empty<LightSignalBinding>();if(source.streetLight){source.streetLight.range=18*scale;source.streetLight.shadowNearPlane=.005f*ratio;}
  for(int i=0;i<source.screens.Length;i++){
   var signal=root.gameObject.AddComponent<SignalBindings>();signal.kind=SignalKind.Flicker;signal.seed=i;Vector3 p=source.screenCentres[i];signal.materials=new[]{new MaterialSignalBinding{material=source.screens[i].sharedMaterial,property="_Brightness"},new MaterialSignalBinding{material=source.screens[i].sharedMaterial,property="_NoiseTime",kind=MaterialSignalKind.Time},new MaterialSignalBinding{material=source.ground.sharedMaterial,property=i==0?"_TV0":"_TV1",kind=MaterialSignalKind.VectorW,basis=new Vector4(p.x,p.y,p.z,1)}};signal.lights=i<source.screenLights.Length&&source.screenLights[i]?new[]{new LightSignalBinding{light=source.screenLights[i],intensity=.0002f*ratio*ratio}}:Array.Empty<LightSignalBinding>();foreach(var b in signal.lights)b.light.range=2.4f*scale;
  }
