  string output=Environment.GetEnvironmentVariable("CONTENT_BUILD_OUTPUT");Directory.CreateDirectory(output);var textureSet=new HashSet<Texture>();var materialSet=new HashSet<Material>(root.GetComponentsInChildren<MeshRenderer>().SelectMany(r=>r.sharedMaterials));foreach(var field in root.GetComponentsInChildren<InstanceField>())foreach(var m in field.materials)materialSet.Add(m);foreach(var m in materialSet)foreach(string property in m.GetTexturePropertyNames())if(m.GetTexture(property))textureSet.Add(m.GetTexture(property));foreach(var lm in maps){if(lm.lightmapColor)textureSet.Add(lm.lightmapColor);if(lm.lightmapDir)textureSet.Add(lm.lightmapDir);if(lm.shadowMask)textureSet.Add(lm.shadowMask);}var textureReport=new Newtonsoft.Json.Linq.JArray();foreach(var texture in textureSet){long bytes=44;int bpp=texture.graphicsFormat.ToString().Contains("Float")?8:4;for(int mip=0;mip<texture.mipmapCount;mip++)bytes+=(long)Math.Max(1,texture.width>>mip)*Math.Max(1,texture.height>>mip)*bpp;textureReport.Add(new Newtonsoft.Json.Linq.JObject{["asset"]=AssetDatabase.GetAssetPath(texture),["width"]=texture.width,["height"]=texture.height,["mips"]=texture.mipmapCount,["encoded_bytes"]=bytes});}
