 }
 static void CheckTexturePixels(){
  string output=Environment.GetEnvironmentVariable("CONTENT_BUILD_OUTPUT");var texture=new Texture2D(2,2,TextureFormat.RGBAHalf,false,true);var expected=new Color(2.5f,.5f,.25f,1);texture.SetPixels(new[]{expected,expected,expected,expected});texture.Apply();var definition=new GameObject("Pixel probe author").AddComponent<SceneDefinition>();var cube=GameObject.CreatePrimitive(PrimitiveType.Cube);UnityEngine.Object.DestroyImmediate(cube.GetComponent<Collider>());definition.contentRoot=cube.transform;var material=new Material(Shader.Find("Universal Render Pipeline/Unlit"));material.SetTexture("_BaseMap",texture);cube.GetComponent<MeshRenderer>().sharedMaterial=material;Texture2D decoded=null;
  try{string path=Path.Combine(output,"texture-pixel-probe.spatial");ScenePackageExporter.Export(definition,path,ExportMode.LocalValidation);var package=SpatialWallpaper.Content.PackageValidator.Validate(path);int index=(int)package.Scene["materials"][0]["properties"]["_BaseMap"]["value"];var bytes=package.Read((string)package.Scene["textures"][index]);decoded=new Texture2D(2,2,(TextureFormat)BitConverter.ToInt32(bytes,12),false,true);decoded.LoadRawTextureData(bytes.Skip(44).ToArray());decoded.Apply();var actual=decoded.GetPixel(0,0);bool passed=Mathf.Abs(actual.r-expected.r)<.001f&&Mathf.Abs(actual.g-expected.g)<.001f&&Mathf.Abs(actual.b-expected.b)<.001f;File.WriteAllText(Path.Combine(output,"reports/texture-pixels.json"),new Newtonsoft.Json.Linq.JObject{["expected"]=new Newtonsoft.Json.Linq.JArray(expected.r,expected.g,expected.b),["actual"]=new Newtonsoft.Json.Linq.JArray(actual.r,actual.g,actual.b),["passed"]=passed}.ToString());if(!passed)throw new InvalidOperationException("texture-pixel-roundtrip-failed");}
  finally{if(decoded)UnityEngine.Object.DestroyImmediate(decoded);UnityEngine.Object.DestroyImmediate(cube);UnityEngine.Object.DestroyImmediate(material);UnityEngine.Object.DestroyImmediate(texture);UnityEngine.Object.DestroyImmediate(definition.gameObject);}
 }
 static byte[] TextureBlockReaderForProbe(Texture2D texture){
  // The exporter already verifies every decoded pixel for its temporary readable
  // clone. Independently read the original compressed asset for payload equality.
  string folder="Assets/HdrProbe-"+Guid.NewGuid().ToString("N");AssetDatabase.CreateFolder("Assets",Path.GetFileName(folder));
  try{string path=folder+"/source.hdr";if(!AssetDatabase.CopyAsset(AssetDatabase.GetAssetPath(texture),path))throw new InvalidOperationException("hdr-probe-copy-failed");var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.isReadable=true;importer.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path).GetRawTextureData();}
  finally{AssetDatabase.DeleteAsset(folder);}
 }
 static void CheckHdrEncoding(){
  string output=Environment.GetEnvironmentVariable("CONTENT_BUILD_OUTPUT");var texture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Parking/Baked/BakeryGround_final.hdr");if(!texture)throw new InvalidOperationException("missing-source-lightmap");var definition=new GameObject("HDR probe author").AddComponent<SceneDefinition>();var cube=GameObject.CreatePrimitive(PrimitiveType.Cube);UnityEngine.Object.DestroyImmediate(cube.GetComponent<Collider>());definition.contentRoot=cube.transform;var material=new Material(Shader.Find("Universal Render Pipeline/Unlit"));material.SetTexture("_BaseMap",texture);cube.GetComponent<MeshRenderer>().sharedMaterial=material;
  try{string path=Path.Combine(output,"hdr-probe.spatial");ScenePackageExporter.Export(definition,path,ExportMode.LocalValidation);var package=SpatialWallpaper.Content.PackageValidator.Validate(path);int index=(int)package.Scene["materials"][0]["properties"]["_BaseMap"]["value"];var bytes=package.Read((string)package.Scene["textures"][index]);int format=BitConverter.ToInt32(bytes,12);bool bc6=texture.graphicsFormat==UnityEngine.Experimental.Rendering.GraphicsFormat.RGB_BC6H_UFloat&&texture.mipmapCount==1;bool passed=format==(int)(bc6?TextureFormat.BC6H:TextureFormat.RGBAHalf);if(bc6)passed=passed&&bytes.Skip(44).SequenceEqual(TextureBlockReaderForProbe(texture));File.WriteAllText(Path.Combine(output,"reports/hdr-format.json"),new Newtonsoft.Json.Linq.JObject{["source_graphics_format"]=texture.graphicsFormat.ToString(),["encoded_texture_format"]=format,["passed"]=passed}.ToString());if(!passed)throw new InvalidOperationException("floating-lightmap-lost-hdr-format");}
  finally{UnityEngine.Object.DestroyImmediate(cube);UnityEngine.Object.DestroyImmediate(material);UnityEngine.Object.DestroyImmediate(definition.gameObject);}
 }
